                const scriptElement = document.getElementById(this.dataSourceId);
                if (!scriptElement) {
                    throw new Error('未找到数据源');
                }

                const yamlContent = scriptElement.textContent.trim();
                if (!yamlContent) {
                    throw new Error('YAML内容为空');
                }

                try {
                    this.yamlData = jsyaml.load(yamlContent);
                } catch (e) {
                    throw new Error(`YAML解析错误: ${e.message}`);
                }
            }

            renderActionOptions() {
                if (!this.yamlData) return;

                // 新格式：直接查找"读者选择"字段
                let options = [];

                if (this.yamlData['读者选择'] && Array.isArray(this.yamlData['读者选择'])) {
                    options = this.yamlData['读者选择'];
                } else {
                    this.handleError(new Error('未找到读者选择字段或格式不正确'));
                    return;
                }

                // 渲染选项列表
                this.elements.optionsList.innerHTML = '';

                if (options.length === 0) {
                    this.elements.optionsList.innerHTML = `
                        <li class="text-center py-4 text-gray-500">
                            <i class="fa fa-info-circle mr-1"></i>没有可用选项
                        </li>
                    `;
                    return;
                }

                options.forEach(optionText => {
                    const cleanOptionText = String(optionText).trim();
                    if (!cleanOptionText) return;

                    const optionItem = document.createElement('li');
                    optionItem.className = 'pl-2 py-2 border-l-2 border-primary/30 ml-1 hover:border-primary/70 transition-colors text-gray-300 rounded';
                    optionItem.textContent = cleanOptionText;
                    this.elements.optionsList.appendChild(optionItem);
                });
            }

            setupEventListeners() {
                document.getElementById('options-container').addEventListener('click', (e) => {
                    if (e.target.tagName === 'LI' && e.target.closest('#options-list')) {
                        const optionText = e.target.textContent.trim();
                        triggerQuickReply(optionText);

                        // 视觉反馈
                        const originalBg = e.target.style.backgroundColor;
                        e.target.style.backgroundColor = 'rgba(157, 124, 245, 0.2)';
                        setTimeout(() => {
                            e.target.style.backgroundColor = originalBg;
                        }, 300);
                    }
                });
            }

            handleError(error) {
                console.error('渲染错误:', error);
                this.elements.optionsList.innerHTML = `
                    <li class="bg-red-900/20 border border-red-800/30 text-red-400 px-4 py-3 rounded">
                        <strong class="font-bold">加载失败: </strong>
                        <span>${error.message}</span>
                    </li>
                `;
            }
        }

        // 页面加载完成后执行
        document.addEventListener('DOMContentLoaded', () => {
            const renderer = new ActionOptionsRenderer('yaml-data-source');
            renderer.init();
        });
    </script>
</body>
</html>
